class Solution:
    def removeDuplicateLetters(self, s: str) -> str:
        last = {c: i for i, c in enumerate(s)}
        st = []; inside = set()
        for i, c in enumerate(s):
            if c in inside: continue
            while st and st[-1] > c and last[st[-1]] > i: inside.discard(st.pop())
            st.append(c); inside.add(c)
        return "".join(st)

