function removeDuplicateLetters(s) {
  // recursive greedy: pick the smallest letter whose suffix still contains all remaining letters
  let out = "";
  while (s.length) {
    const cnt = {}; for (const c of s) cnt[c] = (cnt[c] || 0) + 1;
    let pos = 0;
    for (let i = 0; i < s.length; i++) { if (s[i] < s[pos]) pos = i; if (--cnt[s[i]] === 0) break; }
    const ch = s[pos]; out += ch;
    s = s.slice(pos + 1).split(ch).join("");
  }
  return out;
}
